export const handleValidateAgent = async (field: keyof Agent, studioPro: StudioProApi, agent: Agent): Promise<true | string> => {
    switch (field) {
        case "modelQualifiedName":
            if (!agent.modelQualifiedName) {
                return "Please select a model.";
            }
            const modelDocuments: DocumentsOfTypeResult = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId);
            const matchOfCorrectType = modelDocuments.find(d => d.moduleName + '.' + d.name === agent.modelQualifiedName);
            if (!matchOfCorrectType) {
                return "This document is invalid. Make sure to select a document of type Model."
            }
            break;

        case "entity":
            if (agent.variables.length > 0 && !agent.entity) {
                return "Please select an entity.";
            }
            const [moduleName, entityDocument] = agent.entity.split('.');
            if (agent.entity && (!moduleName || !entityDocument)) {
                return "The selected entity is not valid."
            }
            const isEntityFound = await isAgentEntityFound(studioPro, agent);
            if (!isEntityFound) {
                return "Entity no longer exists."
            }
            break;

        case "userPrompt":
            if (!agent.userPrompt) {
                return "Please provide a user prompt.";
            }
            break;

        default:
            return true;
    }
    return true;
}


export const handleShowModel = async (studioPro: StudioProApi, agent: Agent): Promise<void> => {
    if (!agent.modelQualifiedName) {
        return;
    }
    const model = (await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId)).find(d => d.moduleName + '.' + d.name === agent.modelQualifiedName);
    if (!model) {
        const errorMessage = "Could not find model.";
        const errorDetails = "This model might have been deleted or renamed. Please update the model selection.";
        await studioPro.ui.messageBoxes.show(
            "error",
            errorMessage,
            errorDetails
        );
        return;
    }
    await studioPro.ui.editors.editDocument(model.id);
};

export const handleShowEntity = async (studioPro: StudioProApi, agent: Agent): Promise<void> => {
    if (!agent.entity) {
        return;
    }

    const domainModel = (await getEntity(studioPro, agent.entity))?.getContainer(); // This way we can also check if the entity still exists within the domain model
    if (!domainModel) {
        const errorMessage = "Could not find entity.";
        const errorDetails = "This entity might have been deleted or renamed. Please update the context entity selection.";
        await studioPro.ui.messageBoxes.show(
            "error",
            errorMessage,
            errorDetails
        );
        return;
    }
    await studioPro.ui.editors.editDocument(domainModel.$ID);
};

const updateAgentDocument = async (studioPro: StudioProApi, agent: Agent, documentId: string) => {
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, agent);
    } catch (error) {
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message
        });
    }
};


export const handleEditModelSettings = async (studioPro: StudioProApi, componentName: string, agent: Agent, documentId: string): Promise<Agent | undefined> => {
    const result = await studioPro.ui.dialogs.showModal(
        {
            title: "Model settings",
            contentSize: { height: 385, width: 600 }
        },
        {
            componentName: componentName,
            uiEntrypoint: "modelSettingsEdit",
            queryParams: {
                agent: encodeURIComponent(JSON.stringify(agent))
            }
        }
    );
    let updatedAgent: Agent | undefined = undefined;
    if (result) {
        updatedAgent = result as Agent;
    }
    if (updatedAgent) {
        await updateAgentDocument(studioPro, updatedAgent, documentId);
    }
    return updatedAgent;
};